package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.domain.*; import com.bombay.restaurantintelligence.repository.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestController @RequestMapping("/api") public class ReferenceController {private final CategoryRepository categories;private final IngestionJobRepository jobs;public ReferenceController(CategoryRepository categories,IngestionJobRepository jobs){this.categories=categories;this.jobs=jobs;}@GetMapping("/categories")public List<CategoryView> categories(){return categories.findAll().stream().filter(Category::isActive).sorted(Comparator.comparing(Category::getGroupName).thenComparing(Category::getCode)).map(c->new CategoryView(c.getCode(),c.getName(),c.getGroupName())).toList();}@GetMapping("/imports")public List<ImportView> imports(){return jobs.findTop20ByOrderByCreatedAtDesc().stream().map(j->new ImportView(j.getId(),j.getSourceType(),j.getSourceReference(),j.getStatus(),j.getRecordCount(),j.getCreatedAt())).toList();}@GetMapping("/auth/check")public Map<String,Boolean> auth(){return Map.of("authenticated",true);}public record CategoryView(String code,String name,String group){}public record ImportView(UUID id,String sourceType,String sourceReference,String status,int recordCount,Instant createdAt){} }
